mapper.select:
SELECT count(*) FROM sys_user_role_link rl LEFT JOIN sys_role_menu_link ml ON rl.role_id = ml.role_id AND ml.bool_delete_enum = 0 LEFT JOIN sys_menu menu ON ml.menu_id = menu.id AND menu.bool_delete_enum = 0 where rl.bool_delete_enum = 0
and rl.user_id = #{userId}
and menu.permission = #{permission}
